fn step_id_strategy() -> impl Strategy<Value = String> {
    \"[a-z][a-z0-9_]{0,15}\".prop_filter(\"exclude YAML-ambiguous step IDs\", |s| {
        "'!matches!(
            s.as_str(),
            "y" | "n" | "yes" | "no" | "true" | "false" | "on" | "off"
        )
    })
}

